#!/usr/bin/env bash
# PRUEBA EN SYSTEMD REAL (gestor de usuario de m4rk, systemd 255) con una unidad de prueba que hace de logrotate.timer.
# NO toca logrotate ni ningún servicio del laboratorio. Todo vive en ~/cf-prueba-rot y en unidades cf-prueba-* / cf-4b-* de USUARIO.
set -u
R=$HOME/cf-prueba-rot; U=$HOME/.config/systemd/user; ST=$HOME/.local/share/systemd/timers
mkdir -p $R/bin $R/home $R/suri $R/estado $U $ST
echo "" | base64 -d > $R/bin/cf_4b_rotacion.py
SC="systemctl --user"
cat > $R/bin/sctl <<EOF
#!/bin/sh
exec systemctl --user "\$@"
EOF
cat > $R/bin/srun <<EOF
#!/bin/sh
exec systemd-run --user "\$@"
EOF
cat > $R/bin/cf-4b-rotacion-prueba <<EOF
#!/bin/sh
export CF_HOME=$R/home CF_ESTADO=$R/estado CF_SURICATA=$R/suri CF_SYSTEMCTL=$R/bin/sctl CF_SYSTEMD_RUN=$R/bin/srun CF_SELF=$R/bin/cf-4b-rotacion-prueba CF_TIMER=cf-prueba-logrotate.timer CF_SERVICIO=cf-prueba-logrotate.service CF_PRUEBA=1
exec python3 $R/bin/cf_4b_rotacion.py "\$@"
EOF
chmod +x $R/bin/sctl $R/bin/srun $R/bin/cf-4b-rotacion-prueba
cat > $R/bin/arbol.py <<'PY'
import hashlib, os, sys
from pathlib import Path
R = Path(os.path.expanduser("~/cf-prueba-rot")); H = R / "home"; S = R / "suri"
modo = sys.argv[1]
def wr(p, n): p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes((f"{p.name} linea\n" * n).encode())
if modo == "base":
    for p, n in ((S / "eve.json", 4000), (S / "stats.log", 800), (H / "cyberflow/logs/motor_decision.log", 3000), (H / "cyberflow/logs/_state-e4/ciclos.jsonl", 500),
                 (H / "feed-v2/via-rapida-resumen.jsonl", 1500), (H / "feed-v2/traza.jsonl", 1500), (H / "feed-v2/senales-if.jsonl", 1500)):
        wr(p, n)
    (H / "feed-v2/senales-rapidas.jsonl").write_bytes(b"")
    (R / "tam-motor-base.txt").write_text(str((H / "cyberflow/logs/motor_decision.log").stat().st_size))
else:                                   # cierre | cierre-roto | cierre-base : lo que dejarían la corrida y s40 v2
    B = H / "cf-e4/4b"; C = B / "copias"; (C / "feed-v2").mkdir(parents=True, exist_ok=True); (B / "replay").mkdir(exist_ok=True)
    (B / "replay/rc.txt").write_text("rc=0\n"); (B / "cierre.t").write_text("1.0\n"); (B / "archivo-pcap.rc").write_text("0\n")
    srcs = {"motor_decision.log": H / "cyberflow/logs/motor_decision.log", "ciclos.jsonl": H / "cyberflow/logs/_state-e4/ciclos.jsonl", "stats-fin.log": S / "stats.log",
            "feed-v2/via-rapida-resumen.jsonl": H / "feed-v2/via-rapida-resumen.jsonl", "feed-v2/traza.jsonl": H / "feed-v2/traza.jsonl",
            "feed-v2/senales-if.jsonl": H / "feed-v2/senales-if.jsonl", "feed-v2/senales-rapidas.jsonl": H / "feed-v2/senales-rapidas.jsonl"}
    tam0 = int((R / "tam-motor-base.txt").read_text())
    for n, q in srcs.items():
        if n != "feed-v2/senales-rapidas.jsonl":
            with open(q, "ab") as fh: fh.write(b"registro de la 4B\n" * 20)           # la corrida escribió en las fuentes
        (C / n).write_bytes(q.read_bytes())
    for n, c in (("eve-segmento.json", b"e\n"), ("muestras.jsonl", b"m\n"), ("archivar.log", b"2026 OK live-x.pcap\n"), ("archivador-ESTADO.txt", b"OK vistos=1\n"),
                 ("servicios-fin.txt", b"x\n"), ("sha256-feed-final.txt", b"h\n"), ("feed-v2/feed.json", b"{}\n")):
        (C / n).write_bytes(c)
    (C / "FUENTES-al-copiar.tsv").write_text("".join(f"{n}\t{(C / n).stat().st_size}\n" for n in srcs))
    m = C / "motor_decision.log"
    if modo == "cierre-roto":            # un cp cortado a mitad de línea
        d = m.read_bytes(); m.write_bytes(d[: len(d) // 2])
    if modo == "cierre-base":            # copia IDÉNTICA a la línea base, terminada en línea válida; la fuente ya tiene registros de la 4B
        m.write_bytes(m.read_bytes()[:tam0])
    lista = sorted(str(q.relative_to(C)) for q in C.rglob("*") if q.is_file() and q.name != "SHA256SUMS")
    (C / "SHA256SUMS").write_text("".join(f"{hashlib.sha256((C / n).read_bytes()).hexdigest()}  ./{n}\n" for n in lista))
    (C / "COPIAS-COMPLETAS.ok").write_text("ok\n")
PY
cat > $U/cf-prueba-logrotate.service <<EOF
[Unit]
Description=PRUEBA 4B: hace de logrotate.service (solo anota la hora)
[Service]
Type=oneshot
ExecStart=/bin/sh -c 'date -u +%%FT%%TZ >> $R/marcas-logrotate.txt'
EOF
CP=$R/bin/cf-4b-rotacion-prueba
mk_timer() {   # mk_timer SEGUNDOS_HASTA_EL_ELAPSE : timer diario con Persistent=true, como logrotate.timer; sello = ahora (sin recuperación al arrancar)
  $SC stop cf-prueba-logrotate.timer 2>/dev/null; : > $R/marcas-logrotate.txt
  EL=$(date -u -d "+$1 sec" "+%H:%M:%S")
  printf '[Unit]\nDescription=PRUEBA 4B: hace de logrotate.timer\n[Timer]\nOnCalendar=*-*-* %s UTC\nPersistent=true\nAccuracySec=1s\nUnit=cf-prueba-logrotate.service\n[Install]\nWantedBy=timers.target\n' "$EL" > $U/cf-prueba-logrotate.timer
  $SC daemon-reload; touch $ST/stamp-cf-prueba-logrotate.timer; $SC start cf-prueba-logrotate.timer
  echo "  timer de prueba: elapse diario a las $EL UTC; $($SC show cf-prueba-logrotate.timer -pNextElapseUSecRealtime --value); activo=$($SC is-active cf-prueba-logrotate.timer)"
}
limpiar() {
  $CP desarmar > /dev/null 2>&1; $SC stop cf-4b-vigia.service cf-4b-tope.timer cf-4b-tope.service cf-prueba-logrotate.timer 2>/dev/null
  $SC reset-failed 2>/dev/null; rm -rf $R/estado $R/home $R/suri; mkdir -p $R/estado; python3 $R/bin/arbol.py base
}
esperar() {    # esperar "orden" segundos
  local n=0; while [ $n -lt $2 ]; do eval "$1" && return 0; sleep 2; n=$((n+2)); done; return 1
}
ahora() { date -u +%FT%TZ; }
echo "######## $(ahora)  systemd $($SC --version | head -1 | cut -d' ' -f2) (gestor de usuario)"
limpiar

echo; echo "======== S1 · tope ABSOLUTO + recuperación + Persistent (el elapse del 'logrotate' cae con el timer parado)"
mk_timer 90
TOPE=$(( $(date +%s) + 160 )); echo "  tope absoluto: $(date -u -d @$TOPE '+%F %T') UTC (epoch $TOPE)"
$CP armar --tope $TOPE; echo "  armar rc=$?"
echo "  tras armar: timer de prueba=$($SC is-active cf-prueba-logrotate.timer) tope=$($SC is-active cf-4b-tope.timer) siguiente=$($SC show cf-4b-tope.timer -pNextElapseUSecRealtime --value) vigía=$($SC is-active cf-4b-vigia.service)"
sleep 100; echo "  $(ahora) (ya pasó el elapse diario de la prueba, antes del tope): marcas del 'logrotate' = $(wc -l < $R/marcas-logrotate.txt) ; timer=$($SC is-active cf-prueba-logrotate.timer)"
esperar "[ \$(date +%s) -ge $((TOPE+12)) ]" 120
echo "  $(ahora) (después del tope): timer=$($SC is-active cf-prueba-logrotate.timer) ; marcas del 'logrotate' = $(wc -l < $R/marcas-logrotate.txt) -> $(cat $R/marcas-logrotate.txt | tr '\n' ' ')"
echo "  tope armado ya retirado: $($SC is-active cf-4b-tope.timer 2>&1 | head -1) ; vigía: $($SC is-active cf-4b-vigia.service 2>&1 | head -1)"
echo "  --- log.txt"; sed 's/^/    /' $R/estado/log.txt | tail -8

echo; echo "======== S2 · cierre exitoso con copias verificadas => reanudación NORMAL antes del tope"
limpiar; mk_timer 900
TOPE=$(( $(date +%s) + 420 )); $CP armar --tope $TOPE > /dev/null; echo "  armado rc=$?; timer de prueba=$($SC is-active cf-prueba-logrotate.timer)"
sleep 40; echo "  $(ahora) SIN cierre todavía, tras 40 s: timer=$($SC is-active cf-prueba-logrotate.timer) (debe seguir parado)"
python3 $R/bin/arbol.py cierre; echo "  $(ahora) cierre y copias fieles escritos; cierre => $($CP cierre | tail -1)"
esperar "[ \"\$($SC is-active cf-prueba-logrotate.timer)\" = active ]" 100 && echo "  $(ahora) timer REANUDADO por el vigía: $($SC is-active cf-prueba-logrotate.timer) (antes del tope: faltaban $((TOPE - $(date +%s))) s)" || echo "  NO reanudó"
sed 's/^/    /' $R/estado/log.txt | tail -4

echo; echo "======== S3 · copia incompleta con manifiesto consistente => NO reanuda en normal; solo el tope"
for MODO in cierre-roto cierre-base; do
  echo "  --- variante $MODO"
  limpiar; mk_timer 900
  TOPE=$(( $(date +%s) + 80 )); $CP armar --tope $TOPE > /dev/null; echo "  armado rc=$?"
  sleep 6; python3 $R/bin/arbol.py $MODO
  echo "  $(ahora) manifiesto consistente: $(cd $R/home/cf-e4/4b/copias && sha256sum -c --quiet SHA256SUMS && echo 'sha256sum -c OK'); cierre => $($CP cierre | grep -E 'FALLO|RESULTADO' | cut -c1-200 | tr '\n' '|')"
  sleep 30; echo "  $(ahora) a los ~36 s: timer=$($SC is-active cf-prueba-logrotate.timer) (debe seguir parado)"
  esperar "[ \"\$($SC is-active cf-prueba-logrotate.timer)\" = active ]" 90 && echo "  $(ahora) timer reanudado (tope era $(date -u -d @$TOPE +%T))" || echo "  NO reanudó"
  sed 's/^/    /' $R/estado/log.txt | tail -2
done

echo; echo "======== S4 · desarmar con el arranque del timer FALLIDO (unidad inexistente): no retira vigía ni tope"
limpiar; mk_timer 900
TOPE=$(( $(date +%s) + 150 )); $CP armar --tope $TOPE > /dev/null; echo "  armado rc=$?; timer=$($SC is-active cf-prueba-logrotate.timer)"
mv $U/cf-prueba-logrotate.timer $R/timer.guardado; $SC daemon-reload
$CP desarmar > $R/desarmar1.txt 2>&1; echo "  desarmar con el start imposible: rc=$? ; $(tail -1 $R/desarmar1.txt)"
echo "  tras el fallo: timer=$($SC is-active cf-prueba-logrotate.timer) vigía=$($SC is-active cf-4b-vigia.service) tope=$($SC is-active cf-4b-tope.timer) parado.json=$([ -e $R/estado/parado.json ] && echo sí || echo no)"
mv $R/timer.guardado $U/cf-prueba-logrotate.timer; $SC daemon-reload
$CP desarmar > /dev/null 2>&1; echo "  desarmar con el start posible: rc=$? ; timer=$($SC is-active cf-prueba-logrotate.timer) vigía=$($SC is-active cf-4b-vigia.service 2>&1 | head -1) tope=$($SC is-active cf-4b-tope.timer 2>&1 | head -1)"
sed 's/^/    /' $R/estado/log.txt | tail -4

echo; echo "######## limpieza"
limpiar; $SC stop cf-prueba-logrotate.timer 2>/dev/null
rm -f $U/cf-prueba-logrotate.timer $U/cf-prueba-logrotate.service $ST/stamp-cf-prueba-logrotate.timer; $SC daemon-reload
rm -rf $R
echo "  unidades de prueba restantes: $($SC list-units 'cf-prueba*' 'cf-4b*' --all --no-legend 2>&1 | wc -l) ; ~/cf-prueba-rot: $(ls -d $R 2>&1 | head -1)"
echo "  logrotate.timer (sistema) sin tocar: $(systemctl is-active logrotate.timer) ; último disparo $(systemctl show logrotate.timer -pLastTriggerUSec --value)"
echo "######## FIN $(ahora)"
